def stable_unique(values):
    seen = set()
    result = []
    for v in values:
        if (isinstance(v, (int, str)) and not isinstance(v, bool)):
            key = (type(v).__name__, v)
            if key not in seen:
                seen.add(key)
                result.append(v)
        else:
            result.append(v)
    return result
```

